import raw from "./niche-stacks.data.json";
import type { NicheData, NicheStack } from "./niche-stacks.ts";

/** Generated by automation/build_stacks.py. Edit the data there, not the JSON. */
export const NICHE_DATA = raw as NicheData;

export function getNicheStack(slug: string | null | undefined): NicheStack | null {
  return NICHE_DATA.stacks.find((s) => s.slug === slug) ?? null;
}
